"""Write side: turn edit lists into published revisions."""
from storefront.models import BadRequest, NotFound, Product, Rejected
from storefront.services.validation import check_catalog
from storefront.store.revision import Revision
from storefront.util import sku as sku_rules


class ChangeService:
    def __init__(self, repo, settings):
        self.repo = repo
        self.settings = settings

    def open(self, store):
        if store.startswith("_") or not self.repo.exists(store):
            raise NotFound(f"no store {store}")
        return Revision(self.repo, store, self.settings.scratch_root).begin()

    def apply_edit(self, rev, edit):
        op = edit.get("op")
        sku = edit.get("sku")
        if not sku_rules.is_valid(sku):
            raise BadRequest(f"invalid sku {sku!r}")
        if op == "put":
            rev.put(Product(sku, str(edit.get("name", "")), int(edit.get("price", 0)), int(edit.get("stock", 0))))
        elif op in ("set_price", "set_stock"):
            current = self.repo.get(rev.store, sku)
            if current is None:
                raise BadRequest(f"{sku} is not in {rev.store}")
            field = "price" if op == "set_price" else "stock"
            values = current.to_dict()
            values[field] = int(edit[field])
            rev.put(Product.from_dict(values))
        elif op == "delete":
            rev.delete(sku)
        else:
            raise BadRequest(f"unknown op {op!r}")

    def finish(self, rev):
        problems = check_catalog(self.repo.list(rev.store), self.settings.max_price)
        if problems:
            rev.rollback()
            raise Rejected(problems)
        rev.commit()

    def apply(self, store, edits):
        rev = self.open(store)
        try:
            for edit in edits:
                self.apply_edit(rev, edit)
        except Exception:
            rev.rollback()
            raise
        self.finish(rev)
        return {"store": store, "applied": len(edits), "products": len(self.repo.list(store))}
"""Filesystem helpers shared by the stores."""
import itertools
import json
import os
import shutil

_SEQ = itertools.count()


def write_json(path, data):
    """Write JSON so readers see either the old file or the new one, never a mix."""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    tmp = os.path.join(directory, f".{os.path.basename(path)}.{os.getpid()}-{next(_SEQ)}.tmp")
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, sort_keys=True, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise


def read_json(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def list_json(directory):
    """Names of the *.json files in directory (hidden and temp files skipped)."""
    if not os.path.isdir(directory):
        return []
    return sorted(
        name for name in os.listdir(directory)
        if name.endswith(".json") and not name.startswith(".")
    )


def scratch_dir(root, purpose):
    """Working directory for an operation, created on demand under the scratch root."""
    path = os.path.join(root, purpose)
    os.makedirs(path, exist_ok=True)
    return path


def copy_files(src_dir, dst_dir, names=None):
    os.makedirs(dst_dir, exist_ok=True)
    for name in names if names is not None else list_json(src_dir):
        shutil.copy2(os.path.join(src_dir, name), os.path.join(dst_dir, name))


def remove_files(directory, names):
    for name in names:
        try:
            os.remove(os.path.join(directory, name))
        except FileNotFoundError:
            pass
"""Settings. data_root holds one directory per store; scratch space lives under it."""
import os
from dataclasses import dataclass


@dataclass(frozen=True)
class Settings:
    data_root: str
    scratch_root: str
    import_batch_size: int = 3
    max_price: int = 10_000_000
    shared_store: str = "_shared"

    @classmethod
    def for_root(cls, data_root, **overrides):
        scratch = overrides.pop("scratch_root", os.path.join(data_root, ".scratch"))
        return cls(data_root=data_root, scratch_root=scratch, **overrides)

